return {
    { 1857, "year", "In which year was Flaubert's Madame Bovary published as a book?", "In 1857, after a trial for offending public morals.", "En quelle année Madame Bovary de Flaubert a-t-il paru en volume ?", "En 1857, après un procès pour outrage aux bonnes mœurs.", "src: Madame Bovary" },
    { 1759, "year", "In which year did Voltaire publish Candide?", "In 1759: 'we must cultivate our garden'.", "En quelle année Voltaire a-t-il publié Candide ?", "En 1759 : « il faut cultiver notre jardin ».", "src: Candide" },
    { 1885, "year", "In which year did Émile Zola publish Germinal?", "In 1885, set among the miners of northern France.", "En quelle année Émile Zola a-t-il publié Germinal ?", "En 1885, chez les mineurs du Nord.", "src: Germinal" },
    { 20, "n", "How many novels make up Zola's Rougon-Macquart cycle?", "Twenty, from 1871 to 1893.", "Combien de romans compte le cycle des Rougon-Macquart de Zola ?", "Vingt, de 1871 à 1893.", "src: Les Rougon-Macquart" },
    { 1813, "year", "In which year was Jane Austen's Pride and Prejudice published?", "In 1813, anonymously — 'by the author of Sense and Sensibility'.", "En quelle année Orgueil et Préjugés de Jane Austen a-t-il été publié ?", "En 1813, anonymement.", "src: Pride and Prejudice" },
    { 1719, "year", "In which year was Daniel Defoe's Robinson Crusoe published?", "In 1719, inspired by the castaway Alexander Selkirk.", "En quelle année Robinson Crusoé de Daniel Defoe a-t-il été publié ?", "En 1719, inspiré du naufragé Alexander Selkirk.", "src: Robinson Crusoe" },
    { 28, "years", "How many years does Robinson Crusoe spend on his island?", "28 years, two months and nineteen days, he tells us.", "Combien d'années Robinson Crusoé passe-t-il sur son île ?", "28 ans, deux mois et dix-neuf jours, précise-t-il.", "src: Robinson Crusoe (text)" },
    { 1818, "year", "In which year was Mary Shelley's Frankenstein published?", "In 1818; she started it at 18 during a stormy summer by Lake Geneva.", "En quelle année Frankenstein de Mary Shelley a-t-il été publié ?", "En 1818 ; elle l'a commencé à 18 ans, un été d'orage au bord du Léman.", "src: Frankenstein" },
    { 1897, "year", "In which year was Bram Stoker's Dracula published?", "In 1897; Stoker never visited Transylvania.", "En quelle année Dracula de Bram Stoker a-t-il été publié ?", "En 1897 ; Stoker n'a jamais mis les pieds en Transylvanie.", "src: Dracula" },
    { 1865, "year", "In which year was Alice's Adventures in Wonderland published?", "In 1865, by the mathematician Lewis Carroll.", "En quelle année Alice au pays des merveilles a-t-il été publié ?", "En 1865, par le mathématicien Lewis Carroll.", "src: Alice's Adventures in Wonderland" },
    { 1949, "year", "In which year was George Orwell's Nineteen Eighty-Four published?", "In 1949 — Big Brother is watching you.", "En quelle année 1984 de George Orwell a-t-il été publié ?", "En 1949 — Big Brother vous regarde.", "src: Nineteen Eighty-Four" },
    { 451, "degf", "In Ray Bradbury's title, at what temperature in °F does book paper catch fire?", "Fahrenheit 451 — about 233 °C.", "D'après le titre de Ray Bradbury, à quelle température en °F le papier des livres s'enflamme-t-il ?", "Fahrenheit 451 — environ 233 °C.", "src: Fahrenheit 451" },
    { 24, "n", "How many tales are there in Chaucer's Canterbury Tales?", "24; Chaucer planned many more.", "Combien de contes comptent les Contes de Canterbury de Chaucer ?", "24 ; Chaucer en prévoyait bien plus.", "src: The Canterbury Tales" },
    { 100, "n", "How many cantos make up Dante's Divine Comedy?", "100: one introduction plus 33 for each of Hell, Purgatory and Paradise.", "Combien de chants compte la Divine Comédie de Dante ?", "100 : une introduction plus 33 pour l'Enfer, le Purgatoire et le Paradis.", "src: Divine Comedy" },
    { 24, "n", "How many books make up Homer's Odyssey?", "24 — as many as the Iliad.", "Combien de chants compte l'Odyssée d'Homère ?", "24 — autant que l'Iliade.", "src: Odyssey" },
    { 20, "years", "How many years is Ulysses away from Ithaca, war included?", "Twenty: ten years of war at Troy, ten years of wandering.", "Combien d'années Ulysse est-il loin d'Ithaque, guerre comprise ?", "Vingt : dix ans de guerre à Troie, dix ans d'errance.", "src: Odyssey" },
    { 12, "n", "How many labours did Hercules perform?", "Twelve, from the Nemean lion to Cerberus.", "Combien de travaux Hercule a-t-il accomplis ?", "Douze, du lion de Némée à Cerbère.", "src: Labours of Hercules" },
    { 1869, "year", "In which year was Tolstoy's War and Peace published in full?", "In 1869, after serialisation from 1865.", "En quelle année Guerre et Paix de Tolstoï a-t-il paru en entier ?", "En 1869, après une parution en feuilleton depuis 1865.", "src: War and Peace" },
    { 1851, "year", "In which year was Herman Melville's Moby-Dick published?", "In 1851: 'Call me Ishmael.'", "En quelle année Moby Dick d'Herman Melville a-t-il été publié ?", "En 1851 : « Appelez-moi Ismaël. »", "src: Moby-Dick" },
    { 6, "n", "How many asteroids does the Little Prince visit before coming to Earth?", "Six — Earth is the seventh planet.", "Combien d'astéroïdes le Petit Prince visite-t-il avant d'arriver sur Terre ?", "Six — la Terre est la septième planète.", "src: The Little Prince (text)" },
    { 1844, "year", "In which year did Alexandre Dumas publish The Three Musketeers?", "In 1844, as a newspaper serial.", "En quelle année Alexandre Dumas a-t-il publié Les Trois Mousquetaires ?", "En 1844, en feuilleton.", "src: The Three Musketeers" },
    { 14, "years", "In The Count of Monte Cristo, how many years does Edmond Dantès spend in the Château d'If?", "Fourteen years, before escaping in a dead man's shroud.", "Dans Le Comte de Monte-Cristo, combien d'années Edmond Dantès passe-t-il au château d'If ?", "Quatorze ans, avant de s'évader dans le linceul d'un mort.", "src: The Count of Monte Cristo" },
    { 1872, "year", "In which year does Phileas Fogg set off Around the World in Eighty Days?", "On 2 October 1872, from the Reform Club in London.", "En quelle année Phileas Fogg part-il pour Le Tour du monde en quatre-vingts jours ?", "Le 2 octobre 1872, depuis le Reform Club de Londres.", "src: Around the World in Eighty Days" },
    { 1864, "year", "In which year was Jules Verne's Journey to the Centre of the Earth published?", "In 1864; the heroes enter through an Icelandic volcano.", "En quelle année Voyage au centre de la Terre de Jules Verne a-t-il été publié ?", "En 1864 ; les héros entrent par un volcan islandais.", "src: Journey to the Center of the Earth" },
    { 1937, "year", "In which year was Tolkien's The Hobbit published?", "In 1937; The Lord of the Rings followed in 1954-55.", "En quelle année Le Hobbit de Tolkien a-t-il été publié ?", "En 1937 ; Le Seigneur des anneaux suit en 1954-1955.", "src: The Hobbit" },
    { 20, "n", "In Tolkien's world, how many Rings of Power were made in all, the One Ring included?", "Twenty: three for the Elves, seven for the Dwarves, nine for Men and the One.", "Dans l'univers de Tolkien, combien d'anneaux de pouvoir ont été forgés en tout, l'Anneau unique compris ?", "Vingt : trois pour les Elfes, sept pour les Nains, neuf pour les Hommes et l'Unique.", "src: Rings of Power (Tolkien)" },
    { 1997, "year", "In which year was the first Harry Potter book published?", "In June 1997, after a dozen publishers had turned it down.", "En quelle année le premier tome de Harry Potter a-t-il été publié ?", "En juin 1997, après le refus d'une douzaine d'éditeurs.", "src: Harry Potter and the Philosopher's Stone" },
    { 24, "n", "How many Asterix albums did Goscinny and Uderzo create together?", "24, until Goscinny's death in 1977.", "Combien d'albums d'Astérix Goscinny et Uderzo ont-ils créés ensemble ?", "24, jusqu'à la mort de Goscinny en 1977.", "src: List of Asterix volumes; web-checked" },
    { 221, "n", "At what number on Baker Street does Sherlock Holmes live?", "221B Baker Street, London.", "À quel numéro de Baker Street habite Sherlock Holmes ?", "Au 221B Baker Street, à Londres.", "src: 221B Baker Street" },
    { 1883, "year", "In which year was Stevenson's Treasure Island published as a book?", "In 1883; it gave us the treasure map marked with an X.", "En quelle année L'Île au trésor de Stevenson a-t-il paru en volume ?", "En 1883 ; on lui doit la carte au trésor marquée d'une croix.", "src: Treasure Island" },
    { 15, "cm", "In Gulliver's Travels, about how tall are the Lilliputians?", "Under six inches — about 15 cm.", "Dans Les Voyages de Gulliver, quelle taille font environ les Lilliputiens ?", "Moins de six pouces — environ 15 cm.", "src: Gulliver's Travels (text)" },
    { 1831, "year", "In which year was Victor Hugo's The Hunchback of Notre-Dame published?", "In 1831; its success helped save the cathedral.", "En quelle année Notre-Dame de Paris de Victor Hugo a-t-il été publié ?", "En 1831 ; son succès a aidé à sauver la cathédrale.", "src: Notre-Dame de Paris (novel)" },
    { 175, "n", "How many letters make up Laclos's novel Les Liaisons dangereuses?", "175 letters.", "Combien de lettres composent Les Liaisons dangereuses de Laclos ?", "175 lettres.", "src: Les Liaisons dangereuses" },
    { 1857, "year", "In which year did Baudelaire publish Les Fleurs du mal?", "In 1857 — six poems were banned after a trial.", "En quelle année Baudelaire a-t-il publié Les Fleurs du mal ?", "En 1857 — six poèmes sont censurés après un procès.", "src: Les Fleurs du mal" },
    { 1901, "year", "In which year was the first Nobel Prize in Literature awarded?", "In 1901, to the French poet Sully Prudhomme.", "En quelle année le premier prix Nobel de littérature a-t-il été décerné ?", "En 1901, au poète français Sully Prudhomme.", "src: Nobel Prize in Literature 1901" },
    { 1903, "year", "In which year was the first Prix Goncourt awarded?", "In 1903; the prize is still worth just 10 euros.", "En quelle année le premier prix Goncourt a-t-il été décerné ?", "En 1903 ; le prix n'est doté que de 10 euros.", "src: Prix Goncourt; web-checked" },
    { 1883, "year", "In which year was The Adventures of Pinocchio published as a book?", "In 1883, by Carlo Collodi.", "En quelle année Les Aventures de Pinocchio ont-elles paru en volume ?", "En 1883, par Carlo Collodi.", "src: The Adventures of Pinocchio" },
    { 1894, "year", "In which year was Kipling's The Jungle Book published?", "In 1894, with Mowgli, Baloo and Bagheera.", "En quelle année Le Livre de la jungle de Kipling a-t-il été publié ?", "En 1894, avec Mowgli, Baloo et Bagheera.", "src: The Jungle Book" },
    { 1623, "year", "In which year was Shakespeare's First Folio published?", "In 1623, seven years after his death, with 36 plays.", "En quelle année le Premier Folio de Shakespeare a-t-il été publié ?", "En 1623, sept ans après sa mort, avec 36 pièces.", "src: First Folio" },
    { 36, "n", "How many plays does Shakespeare's First Folio contain?", "36 — half of them had never been printed before.", "Combien de pièces contient le Premier Folio de Shakespeare ?", "36 — dont la moitié n'avaient jamais été imprimées.", "src: First Folio" },
    { 1812, "year", "In which year did the Brothers Grimm publish the first volume of their fairy tales?", "In 1812, with Snow White, Hansel and Gretel and Rapunzel.", "En quelle année les frères Grimm ont-ils publié le premier volume de leurs contes ?", "En 1812, avec Blanche-Neige, Hansel et Gretel et Raiponce.", "src: Grimms' Fairy Tales" },
    { 1697, "year", "In which year did Charles Perrault publish his Tales of Mother Goose?", "In 1697: Cinderella, Puss in Boots, Little Red Riding Hood…", "En quelle année Charles Perrault a-t-il publié ses Contes de ma mère l'Oye ?", "En 1697 : Cendrillon, le Chat botté, le Petit Chaperon rouge…", "src: Histoires ou contes du temps passé" },
    { 1947, "year", "In which year was The Diary of Anne Frank first published?", "In 1947, in Dutch, edited by her father Otto.", "En quelle année le Journal d'Anne Frank a-t-il été publié pour la première fois ?", "En 1947, en néerlandais, édité par son père Otto.", "src: The Diary of a Young Girl" },
    { 19, "years", "How many years did Victor Hugo spend in exile, mostly on Jersey and Guernsey?", "19 years, from 1851 to 1870.", "Combien d'années Victor Hugo a-t-il passées en exil, surtout à Jersey et Guernesey ?", "19 ans, de 1851 à 1870.", "src: Victor Hugo (exile)" },
    { 1532, "year", "In which year did Rabelais publish Pantagruel?", "In 1532; Gargantua followed.", "En quelle année Rabelais a-t-il publié Pantagruel ?", "En 1532 ; Gargantua suit.", "src: Pantagruel" },
